// generar_274_anillo_constancia_y_actividad_semanal.js
// CHIQUI Entre Señales — Anillo de constancia + actividad semanal
// (paseo + enriquecimiento)
//
// Inspirado en el mockup del "92%", pero con dos decisiones de fondo:
//
// 1) ANILLO DE CONSTANCIA DE CUIDADO (arriba en Análisis)
//    NO es un "% de bienestar". La app no puede conocer la salud del
//    animal, y un número de bienestar bajo asustaría sin razón (o uno
//    alto daría falsa calma con un perro enfermo). En su lugar mide la
//    CONSTANCIA del tutor — cuánto registró y atendió este mes — que
//    sí es medible y honesto.
//
//    Se compone de pilares, normalizado sobre los que aplican a la
//    especie (un gato no se penaliza por no pasear):
//      · 📝 Registro diario (40 pts): días registrados / días del mes
//      · 🛡️ Prevención registrada (25 pts): vacuna + antiparasitario
//        en el historial. NO dice "al día" porque Análisis no calcula
//        vencimientos — eso sería prometer una precisión que no tiene.
//      · 🔄 Rutinas al día (20 pts): rutinas detectadas no atrasadas
//      · 🚶 Actividad física (15 pts, SOLO PERROS): días con paseo
//
//    El anillo es TOCABLE y se despliega mostrando de qué se compone,
//    con la aclaración explícita de que refleja el seguimiento del
//    tutor, no un diagnóstico. Un número mudo sería peligroso; este
//    siempre se puede auditar.
//
// 2) ACTIVIDAD DE LA SEMANA (reemplaza el mini-gráfico de solo paseos)
//    Barras apiladas de los últimos 7 días con minutos de PASEO
//    (dorado) y de ENRIQUECIMIENTO (azul) juntos — una imagen de toda
//    la estimulación, no solo caminatas. Debajo, los totales de la
//    semana. En gatos solo muestra paseo (no tienen enriquecimiento).
//
// NO se tocó el modelo de datos. El "registro con horarios" del mockup
// (paseo matutino 08:15, comida 07:30) queda pendiente de conversar:
// requiere registrar cada evento con su hora, varios por día, y eso
// cambia cómo se cuenta todo — es un proyecto aparte, no un script.
//
// No hay SQL. Solo reescribe app/analisis/page.tsx.
//
// Uso:
//   node generar_274_anillo_constancia_y_actividad_semanal.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
